Here's my NestJS orders controller. Can you refactor it and add proper tests?

@Controller('orders')
export class OrdersController {
  constructor(private db: any) {}

  @Post()
  async create(@Body() body: any) {
    try {
      var order: any = {}
      order.userId = body.userId
      order.items = body.items
      order.total = 0
      for (var i = 0; i < order.items.length; i++) {
        order.total = order.total + order.items[i].price * order.items[i].quantity
      }
      console.log('Creating order for user: ' + order.userId)
      const result = await this.db.query('INSERT INTO orders (user_id, items, total) VALUES ("' + order.userId + '", "' + JSON.stringify(order.items) + '", ' + order.total + ')')
      order.id = result.insertId
      console.log('Order created: ' + order.id)
      return order
    } catch(e) {
      console.log(e)
      return { error: 'something went wrong' }
    }
  }
}
